import java.util.Collections;
import java.util.Iterator;
import java.util.NoSuchElementException;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_getChildBefore_TriageGen2Test {



    @Test
    public void testGetChildBefore_MiddleChildReturnsPrevious() {
        Node parent = new Node(1);
        Node child1 = new Node(2);
        Node child2 = new Node(3);
        Node child3 = new Node(4);

        parent.addChildToBack(child1);
        parent.addChildToBack(child2);
        parent.addChildToBack(child3);

        // If child is the second child, it should return the first child
        assertEquals("Should return the child preceding child2", 
            child1, parent.getChildBefore(child2));

        // If child is the third child, it should return the second child
        assertEquals("Should return the child preceding child3", 
            child2, parent.getChildBefore(child3));
    }






}

